# Allocation always runs against ONE command area, so group them.
CLAIMS_BY_SOURCE = {}
for _c in FAKE_CLAIMS:
    CLAIMS_BY_SOURCE.setdefault(_c["source_id"], []).append(_c)


if __name__ == "__main__":
    # Drift check. Regenerate if this reports STALE.
    #
    # Compares BY FARM ID, not by position. This file is grouped by
    # source for readability, while the engine returns demo order, so a
    # positional zip would compare F001 against F012 and report every
    # row as stale when nothing had actually changed.
    from generate import demo_farms
    from farm_agent import build_claims
    from constants import WEATHER_STATES

    live = {c["farm_id"]: c for c in
            build_claims(demo_farms(), WEATHER_STATES["normal"])}
    stored = {c["farm_id"]: c for c in FAKE_CLAIMS}

    missing = sorted(set(live) - set(stored))
    extra = sorted(set(stored) - set(live))
    drift = sorted(f for f in set(live) & set(stored) if live[f] != stored[f])

    if missing or extra or drift:
        if missing:
            print("STALE — engine has farms this file lacks:", missing)
        if extra:
            print("STALE — this file has farms the engine lacks:", extra)
        if drift:
            print("STALE — values changed for:", drift)
            for f in drift:
                for k in sorted(live[f]):
                    if live[f][k] != stored[f].get(k):
                        print(f"    {f}.{k}: {stored[f].get(k)!r} "
                              f"-> {live[f][k]!r}")
        print()
        print("Regenerate: copy the dicts below over FAKE_CLAIMS.")
        print()
        for c in live.values():
            print(c)
    else:
        print(f"fake_claims.py matches the engine exactly — "
              f"{len(FAKE_CLAIMS)} claims across "
              f"{len(CLAIMS_BY_SOURCE)} sources "
              f"({', '.join(f'{k}:{len(v)}' for k, v in sorted(CLAIMS_BY_SOURCE.items()))}).")